INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20501, 'Ezekiel 44:17', 'Ezekiel', 44, 17, '&nbsp;کله چې هغوئ د دننه دربار په دروازو ورننوځى، نو هغوئ دې د کتان جامې واچوى، هغوئ دې د وړئ کپړې نۀ اچوى کله چې د دننه دربار په دروازو يا د خُدائ په کور کښې خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20502, 'Ezekiel 44:18', 'Ezekiel', 44, 18, '&nbsp;هغوئ دې په خپل سر باندې د کتان پټکے او د کتان لاندې کپړې دې خپلو ملاګانو نه ګېرچاپېره وتړى. هغوئ دې داسې څۀ نۀ اغوندى چې په هغوئ خوله راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20503, 'Ezekiel 44:19', 'Ezekiel', 44, 19, '&nbsp;کله چې هغوئ بهرنى دربار ته وځى چرته چې خلق دى، هغوئ دې هغه کپړې وباسى چې هغوئ په کښې خِدمت کولو او دا دې په مقدسو کوټو کښې پرېږدى، او نورې جامې دې واچوى، هسې نه چې هغوئ په خپلو کپړو سره خلق مقدس کړى، او د هغوئ ژوند په خطره کښې واچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20504, 'Ezekiel 44:20', 'Ezekiel', 44, 20, '&nbsp;هغوئ به خپل سرونه نۀ کلوى او نۀ به خپل وېښتۀ اوږدوى، خو هغوئ به د خپل سر وېښتۀ واړۀ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20505, 'Ezekiel 44:21', 'Ezekiel', 44, 21, '&nbsp;يو اِمام دې هم مے ونۀ څښى کله چې دننه دربار ته ننوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20506, 'Ezekiel 44:22', 'Ezekiel', 44, 22, '&nbsp;هغوئ دې کونډو او طلاقو شوو ښځو سره وادۀ ونۀ کړى، هغوئ دې صرف د بنى اِسرائيلو د نسل پېغلو سره يا د اِمامانو کونډو سره وادۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20507, 'Ezekiel 44:23', 'Ezekiel', 44, 23, '&nbsp;هغوئ دې زما خلقو ته د مقدس او عام څيزونو په مينځ کښې د فرق تعليم ورکړى او ورته دې د حرامو او حلالو په مينځ کښې فرق وښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20508, 'Ezekiel 44:24', 'Ezekiel', 44, 24, '&nbsp;په هره لانجه کښې دې اِمامان د قاضى فرائض ادا کړى او دا دې زما د حکمونو په مطابق فېصله کړى. هغوئ دې زما د ټولو مقرر شوو اخترونو دپاره زما په قانون او اصُول باندې عمل وکړى، او هغوئ دې زما د سبت ورځ مقدسه وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20509, 'Ezekiel 44:25', 'Ezekiel', 44, 25, '&nbsp;اِمام دې خپل ځان مړى ته په نزدې ورتلو باندې پليت نۀ کړى، خو کۀ مړ کس يې پلار يا مور، زوئ يا لور، ورور يا ناوادۀ شوې خور وى، نو په دوئ هغه ځان پليتولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20510, 'Ezekiel 44:26', 'Ezekiel', 44, 26, '&nbsp;د پاکېدو نه وروستو، هغه به اووۀ ورځې انتظار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20511, 'Ezekiel 44:27', 'Ezekiel', 44, 27, '&nbsp;په کومه ورځ چې هغه د مقدس کور دننه دربار ته ځى چې هلته په مقدس ځائ کښې خِدمت وکړى، هغه دې د خپل ځان دپاره د ګناه نذرانه پېش کړى، مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20512, 'Ezekiel 44:28', 'Ezekiel', 44, 28, '&nbsp;صرف زۀ به د اِمامانو ميراث يم. تاسو هغوئ ته په بنى اِسرائيلو کښې ملکيت مۀ ورکوئ، زۀ به د هغوئ ملکيت يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20513, 'Ezekiel 44:29', 'Ezekiel', 44, 29, '&nbsp;هغوئ به د غلو نذرانې، د ګناه نذرانې او د ګناه د تاوان نذرانې خورى، او هر څۀ چې په بنى اِسرائيلو کښې مالِک خُدائ ته وقف شوى وى هغه به د هغوئ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20514, 'Ezekiel 44:30', 'Ezekiel', 44, 30, '&nbsp;د ټولو نه اوله ښۀ مېوه او ستاسو ټولې ښې نذرانې به د اِمامانو وى. تاسو به هغوئ ته د زمکې په غله دانه کښې اوله حِصه ورکړئ نو برکت به ستاسو په خاندان نازل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20515, 'Ezekiel 44:31', 'Ezekiel', 44, 31, '&nbsp;اِمامان به هيڅ قسمه څۀ نۀ خورى، مارغۀ يا ځناور چې په خپله مړ وى يا ځناور مړ کړے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20516, 'Ezekiel 45:1', 'Ezekiel', 45, 1, '&nbsp;”تاسو چې کله زمکه د ميراث په توګه تقسيموئ، تاسو به د زمکې يوه حِصه مالِک خُدائ ته د مقدسې علاقې په توګه وقف کړئ چې د دې اوږدوالے دولس نيم کيلوميټره او پلنوالے يې لس کيلوميټره وى، دا ټوله علاقه په کار دے چې مقدسه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20517, 'Ezekiel 45:2', 'Ezekiel', 45, 2, '&nbsp;په دې کښې به يوه حِصه چې اتۀ سوه پينځۀ اويا مربع فټه ده دا به د مقدس ځائ دپاره وى، چې د دې ګېرچاپېره اووۀ اتيا نيم فټه به د کولاو مېدان دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20518, 'Ezekiel 45:3', 'Ezekiel', 45, 3, '&nbsp;په مقدسه علاقه کښې، د يوې برخې اوږدوالے دولس نيم کلوميټره او پلنوالے پينځۀ کلوميټره به وى، په دې کښې به د ټولو نه زيات مقدس ځائ مقدس کور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20519, 'Ezekiel 45:4', 'Ezekiel', 45, 4, '&nbsp;دا به د اِمامانو دپاره د زمکې مقدسه حِصه وى، څوک چې په مقدس کور کښې او د مالِک خُدائ په حضور کښې خِدمت کوى. دا به د هغوئ د کورونو دپاره ځائ وى او هم به د خُدائ د کور دپاره مقدس ځائ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20520, 'Ezekiel 45:5', 'Ezekiel', 45, 5, '&nbsp;دولس نيم کيلوميټره اوږده او پينځۀ کيلوميټره پلنه علاقه به د هغه ليويانو وى، څوک چې د مالِک خُدائ په کور کښې خِدمت کوى، دا به د هغوئ د ښارونو دپاره جائيداد وى چې په کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20521, 'Ezekiel 45:6', 'Ezekiel', 45, 6, '&nbsp;تاسو به ښار ته د جائيداد په توګه درې کيلوميټر پلنه او دولس نيم کيلوميټره اوږده علاقه ورکړئ، د مقدسې حصې سره خوا په خوا، دا به د ټولو بنى اِسرائيلو وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20522, 'Ezekiel 45:7', 'Ezekiel', 45, 7, '&nbsp;”شهزاده به د مقدسې علاقې او د ښار د جائيداد سره دواړو خواګانو ته برخه واخلى. دا به مغرب نه مغرب او مشرق نه مشرق طرف ته غزېدلې وى. په اوږدو به دا د مغرب نه تر مشرق پورې سرحدى قبائيلى علاقو سره برابره پرته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20523, 'Ezekiel 45:8', 'Ezekiel', 45, 8, '&nbsp;په بنى اِسرائيلو کښې به دا زمکه د هغۀ ملکيت وى. او زما شهزادګان به نور زما په خلقو ظلم نۀ کوى، خو د بنى اِسرائيلو قوم ته به اجازت ورکړى چې د خپلو قبيلو پاتې شوې زمکه قبضه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20524, 'Ezekiel 45:9', 'Ezekiel', 45, 9, '&nbsp;”مالِک قادر مطلق خُدائ داسې فرمائى، تاسو کافى لرې لاړئ، اے د بنى اِسرائيلو شهزادګانو. خپل شرارت او ظلم پرېږدئ او هغه څۀ وکړئ څۀ چې د اِنصاف او د صداقت وى. زما د خلقو نه د زمکو قبضه کول بند کړئ، مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20525, 'Ezekiel 45:10', 'Ezekiel', 45, 10, '&nbsp;تاسو له په کار دى چې صحيح تله، صحيح پېمانه او صحيح پاويزه استعمال کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20526, 'Ezekiel 45:11', 'Ezekiel', 45, 11, '&nbsp;حومر دې ستاسو دپاره د ناپ تول معيارى پېمانه وى. ايفه او بَت دواړه د حومر لسمه حِصه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20527, 'Ezekiel 45:12', 'Ezekiel', 45, 12, '&nbsp;د تول دپاره معيارى پېمانه به د سپينو زرو سيکه وى او يوه سيکه به شل جيرې وى. او شپېتۀ سيکې به د يوې منا په اندازه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20528, 'Ezekiel 45:13', 'Ezekiel', 45, 13, '&nbsp;”دا هغه خاص تحفه ده چې تاسو به يې پېش کړئ يعنې، د ايفه شپږمه حِصه د غنمو د هر يو حومر نه او د ايفه شپږمه حِصه د اوربشو د هر يو حومر نه پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20529, 'Ezekiel 45:14', 'Ezekiel', 45, 14, '&nbsp;د تېلو مقرر شوې حِصه، چې په بَت ناپ شوى وى، دا به د هر کُر نه د يو بَت لسمه حِصه وى، په دې کښې لس بَته يا يو حومر وى او لس بَته د يو حومر برابر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20530, 'Ezekiel 45:15', 'Ezekiel', 45, 15, '&nbsp;هم داسې به د بنى اِسرائيلو د څرن د ځائ نه، د دوو سوو ګډو د رمې نه يو ګډ واخستلے شى. دا به د غلې د نذرانې، سوزېدونکې نذرانې او د سلامتۍ د نذرانې دپاره استعمال کړئ او د خلقو دپاره يې کفاره کړئ، مالِک قادر مطلق خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20531, 'Ezekiel 45:16', 'Ezekiel', 45, 16, '&nbsp;د مُلک ټول خلق به په دې خاصو هديو کښې حِصه د اِسرائيل د شهزاده د استعمال دپاره ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20532, 'Ezekiel 45:17', 'Ezekiel', 45, 17, '&nbsp;دا به د شهزاده ذمه وارى وى چې سوزېدونکې نذرانې، د غلې نذرانې او د څښلو نذرانې په اخترونو، نوې مياشت او په سبت کښې او د بنى اِسرائيل قوم په ټولو مقرر شوو مېلو کښې پوره کړى. هغه به د ګناه نذرانې، د غلې نذرانې، سوزېدونکې نذرانې، او د سلامتۍ نذرانې پوره کړى، او د بنى اِسرائيلو قوم دپاره به يې کفاره کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20533, 'Ezekiel 45:18', 'Ezekiel', 45, 18, '&nbsp;”مالِک قادر مطلق خُدائ داسې فرمائى، د وړومبۍ مياشتې په اوله ورځ تاسو به يو ځوان غوَيے چې بې‌عېبه وى واخلئ او مقدس ځائ به پاک کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20534, 'Ezekiel 45:19', 'Ezekiel', 45, 19, '&nbsp;اِمام به لږه وينه د ګناه د نذرانې نه راواخلى او دا به د خُدائ د کور د دروازې په درشل واچوى، د قربان‌ګاه د برنۍ حصې په څلور واړو ګوټونو، او د خُدائ د کور د دننه دربار په چوکاټونو به يې واچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20535, 'Ezekiel 45:20', 'Ezekiel', 45, 20, '&nbsp;تاسو به هم داسې د مياشتې په اوومه ورځ د هغه چا دپاره وکړئ د چا نه چې غېر ارادې يا په ناپوهۍ کښې ګناه وشى، نو تاسو به د خُدائ د کور دپاره کفاره پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20536, 'Ezekiel 45:21', 'Ezekiel', 45, 21, '&nbsp;تاسو د وړومبۍ مياشتې په څوارلسمه ورځ د فسح اختر شروع کړئ، دا اختر به د اوو ورځو دپاره وى، په دې دوران کښې به تاسو بغېر د خمبيرې روټۍ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20537, 'Ezekiel 45:22', 'Ezekiel', 45, 22, '&nbsp;په هغه ورځ به شهزاده يو غوَيے د خپلې ګناه او د خلقو د ګناه د کفارې دپاره پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20538, 'Ezekiel 45:23', 'Ezekiel', 45, 23, '&nbsp;مالِک خُدائ ته به هغه هره ورځ د اختر د دې اوو ورځو په دوران کښې اووۀ غوَيان او اووۀ ګډان چې ټول بې‌عېبه دى د سوزېدونکې نذرانې دپاره پېش کوى او نر چېلے به د ګناه د نذرانې دپاره پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20539, 'Ezekiel 45:24', 'Ezekiel', 45, 24, '&nbsp;هغه به هر غوَيى او ګډ سره يوه ايفه د غلې نذرانه پېش کوى، هر ايفه سره به څلور ليټره تېل هم پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20540, 'Ezekiel 45:25', 'Ezekiel', 45, 25, '&nbsp;د اختر د دې اوو ورځو په دوران کښې، کوم چې د اوومې مياشتې په پينځلسمه ورځ شروع کيږى، هغه به هم داسې نذرانې د ګناه د نذرانې، د سوزېدونکې نذرانې، د غلې او د تېلو نذرانې پېش کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20541, 'Ezekiel 46:1', 'Ezekiel', 46, 1, '&nbsp;”مالِک قادر مطلق خُدائ داسې فرمائى چې، د دننه دربار دروازه کومه چې د نمرخاتۀ په طرف ده هغه دې د کار شپږ واړو ورځو دپاره بنده وى، خو د سبت په ورځ او د نوې مياشتې په ورځ به دا کولاو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20542, 'Ezekiel 46:2', 'Ezekiel', 46, 2, '&nbsp;شهزاده دې دربار ته د بهر د طرف د برنډې د لار نه ورننوځى او د دروازې چوکاټ سره دې ودريږى. اِمامان دې خپلې سوزېدونکې قربانۍ وکړى او د سلامتيا نذرانې دې پېش کړى. هغه دې د دروازې په درشل کښې عبادت وکړى او بيا دې هغه بهر لاړ شى. خو دروازه به تر ماښام پورې کولاو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20543, 'Ezekiel 46:3', 'Ezekiel', 46, 3, '&nbsp;د هر سبت په ورځ او د هرې نوې مياشتې په ورځ دې د دې مُلک خلق د دروازې په درشل کښې د مالِک خُدائ په حضور کښې عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20544, 'Ezekiel 46:4', 'Ezekiel', 46, 4, '&nbsp;سوزېدونکې نذرانه چې شهزاده يې مالِک خُدائ ته د سبت په ورځ پېش کوى دا به شپږ نران ګډورى او يو ګډ وى، ټول به بې‌عېبه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20545, 'Ezekiel 46:5', 'Ezekiel', 46, 5, '&nbsp;د غلې نذرانه چې د ګډ سره ورکوى هغه به يوه ايفه وى او د ګډورو سره به په خپله خوښه د غلې نذرانه ورکړى، هر يو ايفه سره به څلور ليټره تېل پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20546, 'Ezekiel 46:6', 'Ezekiel', 46, 6, '&nbsp;د نوې مياشتې په ورځ به هغه يو غوَيے، شپږ ګډورى او يو ګډ پېش کړى چې ټول بې‌عېبه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20547, 'Ezekiel 46:7', 'Ezekiel', 46, 7, '&nbsp;هغه به يوه ايفه د غلې نذرانه د غوَيى سره پېش کړى، او يوه ايفه به ګډ سره، او د ګډورو سره چې څومره غواړى هغه هومره دې ورکړى، او هرې يوې ايفې سره دې څلور ليټره تېل پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20548, 'Ezekiel 46:8', 'Ezekiel', 46, 8, '&nbsp;کله چې شهزاده ننوځى، هغه به د برنډې د لارې نه دننه لاړ شى، او په هم هغه لار به هغه بهر راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20549, 'Ezekiel 46:9', 'Ezekiel', 46, 9, '&nbsp;کله چې د مُلک خلق د مالِک خُدائ وړاندې په مقررو اخترونو کښې راشى، هغه څوک چې په شمالى دروازه د عبادت دپاره راشى نو هغه به په جنوبى دروازه بهر لاړ شى، او هغه څوک چې په جنوبى دروازه راننوځى هغه به په شمالى دروازه باندې بهر لاړ شى. يو کس به هم په هغه دروازه واپس نۀ ځى په کومه چې راغلى دى، خو هر يو به په مخالف دروازه بهر وځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20550, 'Ezekiel 46:10', 'Ezekiel', 46, 10, '&nbsp;شهزاده به هم هغوئ سره يو ځائ دننه ځى کله چې هغوئ دننه ځى، او بهر به راوځى کله چې هغوئ بهر راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20551, 'Ezekiel 46:11', 'Ezekiel', 46, 11, '&nbsp;په اخترونو او مقرر شوو مېلو کښې، د غلې نذرانه به يو غوَيى سره يوه ايفه وى، يوه ايفه به د ګډ سره وى، او د ګډورو سره چې څومره غواړى هغه هومره دې ورکړى، او هرې يوې ايفې سره څلور ليټره تېل ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20552, 'Ezekiel 46:12', 'Ezekiel', 46, 12, '&nbsp;کله چې شهزاده د خپلې خوښې نذرانه مالِک خُدائ ته پېش کوى، کۀ هغه سوزېدونکې نذرانه وى او يا د سلامتۍ نذرانه وى، هغه دروازه چې مخ يې نمرخاتۀ طرف ته دے هغه به د هغۀ دپاره کولاو کړے شى. هغه به خپله سوزېدونکې نذرانه او يا د سلامتۍ نذرانه داسې پېش کړى څنګه چې هغه د سبت په ورځ کوى. بيا به هغه بهر لاړ شى، او د هغۀ د بهر تلو نه وروستو، به دروازه بنده کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20553, 'Ezekiel 46:13', 'Ezekiel', 46, 13, '&nbsp;”تاسو به هره ورځ د يو کال بې‌عېبه ګډورے مالِک خُدائ ته د سوزېدونکې نذرانې دپاره پېش کوئ، تاسو به ضرور يو سحر بل سحر دا پوره کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20554, 'Ezekiel 46:14', 'Ezekiel', 46, 14, '&nbsp;تاسو به روزانه يو سحر بل سحر د غلې نذرانه پوره کوئ، چې د يوې ايفې شپږمه به وى او پاو باندې يو ليټر تېلو سره به اوړۀ واغږئ. مالِک خُدائ ته د دې غلې د نذرانې پېش کولو حکم د تل دپاره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20555, 'Ezekiel 46:15', 'Ezekiel', 46, 15, '&nbsp;نو د ګډُورى، د غلې او د تېلو نذرانې به هر سحر په مسلسل توګه د سوزېدونکې نذرانې دپاره پېش کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20556, 'Ezekiel 46:16', 'Ezekiel', 46, 16, '&nbsp;”مالِک قادر مطلق خُدائ داسې فرمائى، کۀ چرې شهزاده د خپل وراثت نه يوه تحفه خپلو زامنو کښې يو زوئ له ورکړى، دا به د هغۀ د نسل وى، او دا به په ميراث کښې د هغوئ جائيداد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20557, 'Ezekiel 46:17', 'Ezekiel', 46, 17, '&nbsp;خو کۀ چرې هغه د خپل وراثت نه يوه تحفه خپل يو نوکر له ورکړى، نو نوکر سره به دا تر د آزادۍ د کال پورې وى، خو بيا به دا واپس د شهزاده شى. د هغۀ ميراث صرف د هغۀ د زامنو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20558, 'Ezekiel 46:18', 'Ezekiel', 46, 18, '&nbsp;شهزاده به د خلقو نه ميراث نۀ اخلى، هغوئ به د خپل جائيداد نه نۀ شړى. هغه به خپلو زامنو ته د خپل ميراث نه جائيداد ورکوى، تر دې چې زما په خلقو کښې يو هم د خپل جائيداد نه محرومه نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20559, 'Ezekiel 46:19', 'Ezekiel', 46, 19, '&nbsp;بيا هغه سړى زۀ د دروازې په خوا کښې مقدسو کوټو ته بوتلم چې مخې يې د شمال ته طرف وې، کومې چې د اِمامانو وې، او ما ته يې د نمر پرېوتو طرف ته ځائ وښودلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20560, 'Ezekiel 46:20', 'Ezekiel', 46, 20, '&nbsp;هغۀ ما ته ووئيل چې، ”دا هغه ځائ دے چرته به چې اِمامان د ګناه د تاوان نذرانې او د ګناه نذرانې او د غلې نذرانې پخوى، ترڅو بهرنى دربار ته د مقدسو څيزونو د راوړلو نه منع شى هسې نه چې خلق مقدسو څيزونو له لاس وروړى او خپل ژوند په خطره کښې واچوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20561, 'Ezekiel 46:21', 'Ezekiel', 46, 21, '&nbsp;بيا هغۀ زۀ بهرنى دربار ته راوستلم او په دې کښې يې ګوټ په ګوټ وګرځولم او ما په هر ګوټ کښې بل دربار وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20562, 'Ezekiel 46:22', 'Ezekiel', 46, 22, '&nbsp;د بهرنى دربار په څلور واړو ګوټونو کښې يو بل سره انښتى دربارونه وُو، چې اويا فټه اوږد او دوه پنځوس نيم فټه پلن وُو او په څلور واړو ګوټونو کښې هر يو دربار يو شان برابر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20563, 'Ezekiel 46:23', 'Ezekiel', 46, 23, '&nbsp;دننه د څلور واړو دربارونو ګېرچاپېره د کاڼى يوه چجه وه، د چجې لاندې ګېرچاپېره د اور بلېدلو نغرى جوړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20564, 'Ezekiel 46:24', 'Ezekiel', 46, 24, '&nbsp;هغۀ ما ته ووئيل چې، ”دا هغه باورچې خانې دى چرته به چې هغه څوک چې د خُدائ په کور کښې خِدمت کوى د خلقو قربانۍ پخوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20565, 'Ezekiel 47:1', 'Ezekiel', 47, 1, '&nbsp;هغه سړى زۀ بيا د مالِک خُدائ د کور دروازې ته راوستلم، او ما وليدل چې د خُدائ د کور د درشل د لاندې نه اوبۀ د نمرخاتۀ طرف ته راروانې وې ځکه چې د مالِک خُدائ د کور مخه نمرخاتۀ طرف ته وه. اوبۀ د مالِک خُدائ د کور د جنوب خوا نه ښکته د قربان‌ګاه جنوب خوا ته راروانې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20566, 'Ezekiel 47:2', 'Ezekiel', 47, 2, '&nbsp;نو بيا هغۀ زۀ په شمالى دروازه باندې بهر راوويستلم او زۀ يې بهر راتاو کړم بهرنۍ دروازې ته يې بوتلم چې مخه يې مشرق ته وه، او اوبۀ د جنوب طرف نه رابهېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20567, 'Ezekiel 47:3', 'Ezekiel', 47, 3, '&nbsp;کله چې هغه سړے فيته په لاس نمرخاتۀ طرف ته لاړو، نو هغۀ نيم کيلوميټر ناپ وکړو او بيا يې زۀ په اوبو کښې بوتلم چې د ګيټو پورې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20568, 'Ezekiel 47:4', 'Ezekiel', 47, 4, '&nbsp;هغۀ نور نيم کيلوميټر ناپ وکړو او زۀ يې په اوبو کښې بوتلم چې تر ګوډو پورې ډوبې وې. هغۀ بيا نور نيم کيلوميټر ناپ وکړو او زۀ يې په اوبو کښې بوتلم چې دا تر ملا پورې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20569, 'Ezekiel 47:5', 'Ezekiel', 47, 5, '&nbsp;هغۀ نور نيم کيلوميټر ناپ وکړو، خو اوس دا سيند شو چې زۀ په کښې نۀ شوم اوړېدلے، ځکه چې اوبۀ اوچتې وې او لامبلو ته کافى ډوبې وې، داسې سيند ترې جوړ شو چې هيڅوک په کښې نۀ شُو اوړېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20570, 'Ezekiel 47:6', 'Ezekiel', 47, 6, '&nbsp;بيا هغۀ ما نه تپوس وکړو چې، ”اے بنى آدمه، تۀ دا وينې؟“ نو بيا هغۀ زۀ واپس د درياب غاړې ته بوتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20571, 'Ezekiel 47:7', 'Ezekiel', 47, 7, '&nbsp;کله چې زۀ هلته ورسېدم، نو ما د سيند په دواړو طرفونو ډيرې ونې وليدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20572, 'Ezekiel 47:8', 'Ezekiel', 47, 8, '&nbsp;هغۀ ما ته ووئيل چې، ”دا اوبۀ نمرخاتۀ مُلک طرف ته بهيږى او د اُردن وادۍ ته ځى، چرته چې دا مړ درياب ته ورپرېوځى. کله چې دا مړ درياب ته ورښکته شى، نو په هغې کښې مالګينې اوبۀ تازه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20573, 'Ezekiel 47:9', 'Ezekiel', 47, 9, '&nbsp;د ژوندو ځناورو سيلونه به هلته اوسى چرته چې سيند بهيږى. هلته به ډېر زيات کبان وى، ځکه چې دا اوبۀ هلته بهيږى او مالګې اوبۀ تازه کوى، نو چې چرته دا سيند بهيږى هر څۀ به هلته ژوندى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20574, 'Ezekiel 47:10', 'Ezekiel', 47, 10, '&nbsp;ماهيګران به د سيند په غاړه ولاړ وى، د عين‌جدى نه تر عين‌عجليم پورې به د کبانو د جالونو خورولو دپاره ځايونه وى. لکه د غټ سمندر د کبانو په شان به په کښې ډېر قسمونه کبان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20575, 'Ezekiel 47:11', 'Ezekiel', 47, 11, '&nbsp;خو دلدلې او ډنډونه به تازه نۀ شى، دا به د مالګې دپاره پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20576, 'Ezekiel 47:12', 'Ezekiel', 47, 12, '&nbsp;د هر قسم مېوې ونې به د سيند په دواړو غاړو غټې شى. د دې پاڼې به نۀ وچيږى، او نۀ به د دې مېوې وچيږى. هره مياشت به دا مېوه نيسى، ځکه چې د مالِک خُدائ د مقدس کور نه دې ته اوبۀ بهيږى. د دې مېوه به د خوراک دپاره او پاڼې به يې د شفا دپاره استعماليږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20577, 'Ezekiel 47:13', 'Ezekiel', 47, 13, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، ”دا هغه سرحدونه دى په کومو به چې تۀ زمکه د بنى اِسرائيلو د دولسو قبيلو په مينځ کښې ميراث دپاره تقسيم کړې. د يوسف د اولاد دپاره به دوه حصې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20578, 'Ezekiel 47:14', 'Ezekiel', 47, 14, '&nbsp;تۀ دا د هغوئ په مينځ کښې برابر تقسيم کړه، ځکه چې ما قسم خوړلے وو چې دا به ستاسو پلار نيکۀ له ورکړم، دا زمکه به ستاسو ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20579, 'Ezekiel 47:15', 'Ezekiel', 47, 15, '&nbsp;دا به د دې زمکې سرحد وى، شمال طرف ته به دا د لوئ سمندر نه د حتلون په لار ليبو‌حمات نه صداد ته تېر شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20580, 'Ezekiel 47:16', 'Ezekiel', 47, 16, '&nbsp;بيا به دا د بيروته او سبريم کوم چې د دمشق او حمات د سرحد په مينځ کښې پروت دے، او داسې تر حزر‌هاتيکان پورې، کوم چې د حوران سرحد سره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20581, 'Ezekiel 47:17', 'Ezekiel', 47, 17, '&nbsp;دا سرحد به د سمندر نه تر حصر عينان پورې، د دمشق شمالى سرحد سره، او د حمات سرحد سره شمال طرف ته تلے وى. دا به شمالى سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20582, 'Ezekiel 47:18', 'Ezekiel', 47, 18, '&nbsp;د نمرخاتۀ طرف سرحد به د حوران او دمشق په مينځ کښې، اُردن سره د جِلعاد او د اِسرائيل د خاورې په مينځ کښې، مشرقى سمندر او داسې تر تمر پورې تلے وى. دا به مشرقى سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20583, 'Ezekiel 47:19', 'Ezekiel', 47, 19, '&nbsp;په جنوبى طرف کښې دا به د تامار نه د مريبه قادِس د اوبو پورې وى، بيا به د مِصر د وادۍ نه د لوئ سمندر پورې وى. دا به جنوبى سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20584, 'Ezekiel 47:20', 'Ezekiel', 47, 20, '&nbsp;د مغرب طرف ته به د لوئ سمندر سرحد ليبو‌حمات ته مخامخ وى. دا به مغربى سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20585, 'Ezekiel 47:21', 'Ezekiel', 47, 21, '&nbsp;تاسو به دا زمکه په خپل مينځ کښې د بنى اِسرائيلو د قبيلو په مطابق تقسيم کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20586, 'Ezekiel 47:22', 'Ezekiel', 47, 22, '&nbsp;دا به تاسو د خپل ځان دپاره او هغه غېر مُلکيانو دپاره چې ستاسو په مينځ کښې اوسيږى او د چا چې ماشومان دى د ميراث په توګه تقسيم کړئ. تاسو به هغوئ د پېدائشى بنى اِسرائيلو په شان ګڼئ، تاسو سره به هغوئ ته هم ميراث د بنى اِسرائيلو د قبيلو په شان ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20587, 'Ezekiel 47:23', 'Ezekiel', 47, 23, '&nbsp;په هر يو قوم کښې چې غېر مُلکى خلق اوسيږى، هلته به تاسو هغوئ له خپل ميراث ورکړئ، دا مالِک قادر مطلق خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20588, 'Ezekiel 48:1', 'Ezekiel', 48, 1, '&nbsp;”دا هغه قبيلې دى چې نومونه يې دلته ليکلے شوى دى، د شمالى سرحد سره به د دان يوه حِصه وى، دا به د حتلون په لار ليبو‌حمات پورې وى، حصر عينان او د دمشق شمالى سرحد به حمات پسې وى دا به د مشرق طرف نه د مغرب طرف ته د دې د سرحد حِصه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20589, 'Ezekiel 48:2', 'Ezekiel', 48, 2, '&nbsp;د آشر به يوه حِصه وى، د دې سرحد به د دان حدودو سره د مشرق نه مغرب پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20590, 'Ezekiel 48:3', 'Ezekiel', 48, 3, '&nbsp;يوه حِصه به د نفتالى وى، دا به د آشر د علاقې د مشرق نه مغرب پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20591, 'Ezekiel 48:4', 'Ezekiel', 48, 4, '&nbsp;يوه حِصه به د منسى د قبيلې وى، دا به د نفتالى د علاقې د مشرق نه مغرب پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20592, 'Ezekiel 48:5', 'Ezekiel', 48, 5, '&nbsp;يوه حِصه به د اِفرائيم وى، دا به د منسى د علاقې د مشرق نه مغرب پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20593, 'Ezekiel 48:6', 'Ezekiel', 48, 6, '&nbsp;يوه حِصه به د روبين وى، دا به د اِفرائيم د علاقې د مشرق نه مغرب پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20594, 'Ezekiel 48:7', 'Ezekiel', 48, 7, '&nbsp;يوه حِصه به د يهوداه وى، دا به د روبين د علاقې د مشرق نه مغرب پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20595, 'Ezekiel 48:8', 'Ezekiel', 48, 8, '&nbsp;د يهوداه د سرحد سره چې کومه علاقه د مشرق نه تر مغرب پورې ده دا به هغه حِصه وى چې تۀ يې د خاص تحفې په طور پېش کړې. دا به دولس نيم کيلوميټره پلنه وى، او د دې اوږدوالے د مشرق نه مغرب پورې به د يوې قبائيلى حصې برابر وى، د مالِک خُدائ کور به د دې په مينځ کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20596, 'Ezekiel 48:9', 'Ezekiel', 48, 9, '&nbsp;هغه خاص حِصه چې تۀ يې مالِک خُدائ ته وقف کوې دا به دولس نيم کيلوميټره اوږده او لس کيلوميټره پلنه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20597, 'Ezekiel 48:10', 'Ezekiel', 48, 10, '&nbsp;دا به د اِمامانو دپاره مقدسه حِصه وى. دا به په شمالى طرف دولس نيم کيلوميټره اوږده وى، او په مغربى طرف به پينځۀ کيلوميټره پلنه وى، مشرق طرف ته به پينځۀ کيلوميټره پلنه او جنوبى طرف ته به دولس نيم کيلوميټره اوږده وى. د دې په مينځ کښې به د مالِک خُدائ مقدس کور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20598, 'Ezekiel 48:11', 'Ezekiel', 48, 11, '&nbsp;دا به د مقدسو اِمامانو، د صدوقيانو دپاره وى، څوک چې زما په خِدمت کولو کښې وفادار وُو او بې‌لارې نۀ شول څنګه چې ليويان شول کله چې بنى اِسرائيل بې‌لارې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20599, 'Ezekiel 48:12', 'Ezekiel', 48, 12, '&nbsp;دا به هغوئ ته د زمکې د مقدسې حصې نه خاص تحفه، او د ټولو نه مقدسه حِصه وى، د ليويانو د علاقې سرحد سره به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20600, 'Ezekiel 48:13', 'Ezekiel', 48, 13, '&nbsp;د اِمامانو علاقې سره نزدې، ليويانو ته به هم دولس نيم کيلوميټره اوږده او پينځۀ کيلوميټره پلنه زمکه ورکړے شى. د دې مکمل اوږدوالے به دولس نيم کيلوميټره او پلنوالے به يې پينځۀ کيلوميټره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');